"""Unified Confusion-Retrieval Memory.

Replaces the two-phase selection in adaptive_tokenizer_confusion_memory with a
single-pass unified ranking. Every example receives one score:

    score(ex) = jaccard(query, ex) + ALPHA * log(1 + confusion_affinity(ex.label))

where confusion_affinity is the total confusion-matrix weight between ex.label
and any of the top-K candidate labels inferred from the current ranked list.

Motivation: the two-phase approach injects confusion-target slots unconditionally,
burning context budget on examples that are topically distant from the query. The
unified score ensures that confusion-adjacent examples are only surfaced when they
also bear some semantic similarity to the query.

Also includes the prediction-normalization fix (stripping format wrappers before
storing confusion keys) so the confusion matrix actually fires.
"""

import json
import math
import re
from collections import defaultdict
from typing import Any

from ..llm import LLMCallable
